// @r_peredelkino · explicit scenario assumptions, not measured traffic forecasts.
export const trafficPresets=Object.freeze({night:{name:'Ночь',density:.32,speed:1},day:{name:'День',density:.70,speed:1},morning:{name:'Утро',density:1,speed:.85},evening:{name:'Вечер',density:.96,speed:.8}});
export function trafficPeriod(minutes){const hour=minutes/60;return hour>=7&&hour<10?'morning':hour>=17&&hour<20?'evening':hour>=22||hour<6?'night':'day';}
export function parkingQueue({arrivalsPerHour=250,serviceSeconds=8,lanes=1,blockedPercent=0,durationMinutes=60}={}){
 if(!Number.isFinite(arrivalsPerHour+serviceSeconds+lanes+blockedPercent+durationMinutes)||arrivalsPerHour<0||arrivalsPerHour>3000||serviceSeconds<=0||serviceSeconds>120||!Number.isInteger(lanes)||lanes<1||lanes>4||blockedPercent<0||blockedPercent>95||durationMinutes<=0||durationMinutes>120)throw new RangeError('Invalid parking queue scenario');
 const horizon=durationMinutes*60,service=serviceSeconds/(1-blockedPercent/100),capacity=3600*lanes/service,free=Array(lanes).fill(0),starts=[],waits=[];
 if(arrivalsPerHour>0)for(let i=0;i<Math.ceil(arrivalsPerHour*durationMinutes/60);i++){const at=i*3600/arrivalsPerHour;if(at>=horizon)break;const lane=free.indexOf(Math.min(...free)),start=Math.max(at,free[lane]);starts.push(start);waits.push(start-at);free[lane]=start+service;}
 return{capacity,vehicles:waits.length,averageWait:waits.length?waits.reduce((a,b)=>a+b,0)/waits.length:0,maxWait:Math.max(0,...waits),queueAtEnd:starts.filter(t=>t>=horizon).length,utilisation:arrivalsPerHour/capacity,assumptions:'Even arrivals; constant service; blocked time spread uniformly; no interaction with measured junctions. Finite-horizon scenario only.'};
}
export function mountTrafficScenarios(panel,traffic){
 const section=document.createElement('details');section.className='env-traffic';section.innerHTML=`<summary>Трафик и очередь на выезде</summary><label>Период<select data-traffic-period><option value="auto">По времени Солнца</option><option value="morning">Утро</option><option value="day">День</option><option value="evening">Вечер</option><option value="night">Ночь</option></select></label><p data-traffic-status role="status"></p><p>Число машин и скорости — сценарий. Маршруты используют существующую дорожную схему модели; фазы светофоров демонстрационные.</p><strong>Сценарий выезда из паркинга · 60 минут</strong><label>Машин в час<input data-queue-rate type="number" min="0" max="3000" step="10" value="250"></label><label>Обслуживание одной машины, с<input data-queue-service type="number" min="1" max="120" step="1" value="8"></label><label>Полос выезда<input data-queue-lanes type="number" min="1" max="4" step="1" value="1"></label><label>Время блокировки выезда, %<input data-queue-blocked type="number" min="0" max="95" step="5" value="20"></label><output data-queue-result role="status"></output><p>Вводите свои допущения. Расчёт предполагает равномерные приезды и постоянное время обслуживания. Точное положение рампы и её пропускная способность требуют схемы паркинга.</p>`;
 panel.querySelector('.env-content').append(section);let last='';
 function calculate(){const value=name=>Number(section.querySelector('[data-queue-'+name+']').value),out=section.querySelector('[data-queue-result]');try{const q=parkingQueue({arrivalsPerHour:value('rate'),serviceSeconds:value('service'),lanes:value('lanes'),blockedPercent:value('blocked')});out.textContent=`Пропускная способность ≈ ${Math.round(q.capacity)} машин/ч. Среднее ожидание ${q.averageWait.toFixed(0)} с; максимальное ${Math.ceil(q.maxWait)} с; очередь к концу часа ${q.queueAtEnd} машин. ${q.utilisation>=1?'Поток превышает обслуживание — очередь растёт.':'Обслуживание успевает за равномерным потоком.'}`;section.dataset.queue=JSON.stringify(q);}catch{out.textContent='Проверьте диапазоны исходных значений.';delete section.dataset.queue;}}
 section.querySelectorAll('input').forEach(el=>el.oninput=calculate);calculate();
 return{update(minutes,weather){const selected=section.querySelector('[data-traffic-period]').value,period=selected==='auto'?trafficPeriod(minutes):selected,key=period+':'+weather;if(key!==last){traffic.setScenario({period,weather});last=key;}const stats=traffic.getScenario();section.querySelector('[data-traffic-status]').textContent=`${trafficPresets[period].name} · ${stats.activeCars} машин в анимации · ${weather==='rain'?'мокрое покрытие':weather==='snow'?'снег':'обычные условия'}`;section.dataset.period=period;},dispose(){section.remove();}};
}
